// Open: Sun-Thu 08:30-16:30, Fri 08:30-14:00, Sat closed.
const _p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date()).map(x => [x.type, x.value]));
const _DOW = { Sun:0, Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6 }[_p.weekday];
const _HE = ['\u05e8\u05d0\u05e9\u05d5\u05df','\u05e9\u05e0\u05d9','\u05e9\u05dc\u05d9\u05e9\u05d9','\u05e8\u05d1\u05d9\u05e2\u05d9','\u05d7\u05de\u05d9\u05e9\u05d9','\u05e9\u05d9\u05e9\u05d9','\u05e9\u05d1\u05ea'];
const _hr = _p.hour === '24' ? '00' : _p.hour;
const _mins = Number(_hr) * 60 + Number(_p.minute);
let _open;
if (_DOW === 6) _open = false;
else if (_DOW === 5) _open = _mins >= 510 && _mins < 840;
else _open = _mins >= 510 && _mins < 990;
const _hhmm = _hr + ':' + _p.minute;
const _state = _open ? '\u05e4\u05ea\u05d5\u05d7 \u05db\u05e8\u05d2\u05e2' : '\u05e1\u05d2\u05d5\u05e8 \u05db\u05e8\u05d2\u05e2 (\u05de\u05d7\u05d5\u05e5 \u05dc\u05e9\u05e2\u05d5\u05ea \u05d4\u05e4\u05e2\u05d9\u05dc\u05d5\u05ea)';
