// the agent sees 'שלחתי את הגרפיקה תסתכל' with no idea what was sent. Prepend a
// system-style marker so the LLM can resolve the reference.
let quotedPrefix = '';
for (const m of msgs) {
  const ctx = m.context || {};
  const quotedContent = ctx.quoted_content || '';
  const quotedType = ctx.quoted_type || '';
  const quotedAuthor = ctx.quoted_author || '';
  if (quotedContent || quotedType) {
    const fromBot = quotedAuthor && quotedAuthor.indexOf('507506702') >= 0;
    const who = fromBot ? 'בוט/הצוות' : 'הלקוח עצמו';
    // quoted_content is a MessageContent OBJECT (varies by type), not a string — extract the
    // meaningful text; never stringify the whole object (it carries a huge base64 preview).
    let _qtext = '';
    if (typeof quotedContent === 'string') { _qtext = quotedContent; }
    else if (quotedContent && typeof quotedContent === 'object') { _qtext = quotedContent.body || quotedContent.caption || (quotedContent.text && quotedContent.text.body) || quotedContent.file_name || quotedContent.filename || quotedContent.name || quotedContent.address || ''; }
    const _typeLabel = { image: 'תמונה', video: 'סרטון', document: 'קובץ', audio: 'הקלטה', voice: 'הקלטה קולית', sticker: 'מדבקה', location: 'מיקום', contact: 'איש קשר' }[quotedType] || (quotedType || 'מדיה');
    const body = String(_qtext || ('(' + _typeLabel + ')')).slice(0, 280);
    quotedPrefix += '[הלקוח השיב על הודעה קודמת מ-' + who + ': "' + body + '"]\n';
  }
}
