const hasHebrew  = /[\u0590-\u05FF]/.test(t);
const hasForeign = /[A-Za-z\u0600-\u06FF\u0400-\u04FF]/.test(t);
if (!hasHebrew && hasForeign) { return []; }
return [{ json: d }];

const msg = $('Webhook (WHAPI In)').item.json.body.messages[0];
const chatId = msg.chat_id;
const text = (msg.text && msg.text.body ? msg.text.body : '').toString();
const norm = text.replace(/\s+/g, ' ').trim();

// Payment words (the owner declaring THIS chat is paid/closed).
const PAY = /(שולם|שילם|שולמה|סגור|סגורה|נסגר|נסגרה)/;

// Reported-speech / quoting markers => the owner is quoting the CUSTOMER, not
// declaring payment himself. Also a question mark => not a declaration.
const REPORTED = /(אמר|אמרה|כתב|כתבה|טוען|טוענת|לדבריו|לדבריה|לפי|מבקש|שואל|כאילו|"|״|')/;
const isQuestion = /\?/.test(norm);
// "the customer paid?" style or long narration shouldn't lock the chat for a day.
