// Normalize any size format the agent emits into one line per size.
// Handles "20 M, 5 L" | "6L 1XL" | "1 XXL, 1 XL" | "5M, 28L, 13XL" | "25 M" | kids "(18)"
const raw = $('Parse Order').item.json.o_sizes;
function formatSizes(rawV) {
  if (!rawV) return '';
  const s = String(rawV).trim();
  if (s === '—' || s === '-' || /לתיאום|מול הצוות/.test(s)) return s;
  const pairs = [];
  const reNumFirst = /(\d+)\s*([A-Za-z]{1,4}|\(\d+\))/g;
  const reSizeFirst = /([A-Za-z]{1,4}|\(\d+\))\s*(\d+)/g;
  let m; const found = [];
  while ((m = reNumFirst.exec(s)) !== null) found.push({ qty: parseInt(m[1],10), size: m[2].toUpperCase() });
  if (found.length > 0) { for (const f of found) pairs.push(f); }
  else { while ((m = reSizeFirst.exec(s)) !== null) pairs.push({ qty: parseInt(m[2],10), size: m[1].toUpperCase() }); }
  if (pairs.length === 0) return s;
  return pairs.map(p => p.size.replace(/[()]/g,'') + ' × ' + p.qty).join('\n');
}
const sizesFormatted = formatSizes(raw);
// pass everything through + the new field
return [{ json: { ...$('Parse Order').item.json, sizesFormatted } }];

const j = $('Extract Media').item.json;
const cap = (j.caption || '').toLowerCase();
const fn  = (j.filename || '').toLowerCase();
const text = cap + ' ' + fn;

// Receipt / proof-of-payment signals (Hebrew + common English)
