// Graphic / mockup signals
const GRAPHIC = /(גרפיקה|לוגו|עיצוב|מוקאפ|הדפסה|דגם|mockup|design|logo|אמנות|קובץ|תמונה|print|איור)/i;

let kind = '';            // 'receipt' | 'graphic' | ''
if (RECEIPT.test(text)) kind = 'receipt';
else if (GRAPHIC.test(text)) kind = 'graphic';

// Decide whether to ask Gemini Vision to read the file.
// FIX: PDFs (documents) must also go through Vision — Gemini can OCR a PDF.
// - image: always let Vision look (it confirms kind + reads payer name + amount).
// - document (pdf): let Vision look UNLESS we already know it's a graphic by keyword.
let needsVision = false;
if (j.type === 'image') {
  needsVision = true;                 // any photo -> Vision reads it
} else if (j.type === 'document') {
  if (kind !== 'graphic') needsVision = true;  // pdf receipt / ambiguous pdf -> Vision (OCR)
  else needsVision = false;                     // a pdf clearly tagged as artwork -> skip
}

// If we are NOT sending to Vision and still have no kind, treat a doc as artwork.
if (!needsVision && !kind) {
  kind = (j.type === 'image') ? '' : 'graphic';
}

return [{ json: { ...j, kind, needsVision, rcpt_name: '', rcpt_amount: 0 } }];

// Download WHAPI media, detect type, and pre-build the Gemini body.
// FIX: now supports PDF (application/pdf) in addition to images — Gemini OCRs it.
const j = $('Classify Media').item.json;
const token = 'FDPRDy6fE6JVVUQPphKgaKECwSw6MagO'; // WHAPI channel token

function sniffMime(b){
  if (!b || b.length < 12) return '';
  if (b[0]===0x25 && b[1]===0x50 && b[2]===0x44 && b[3]===0x46) return 'application/pdf'; // %PDF
  if (b[0]===0xFF && b[1]===0xD8 && b[2]===0xFF) return 'image/jpeg';
  if (b[0]===0x89 && b[1]===0x50 && b[2]===0x4E && b[3]===0x47) return 'image/png';
  if (b[0]===0x47 && b[1]===0x49 && b[2]===0x46 && b[3]===0x38) return 'image/gif';
  if (b[0]===0x52 && b[1]===0x49 && b[2]===0x46 && b[3]===0x46 &&
      b[8]===0x57 && b[9]===0x45 && b[10]===0x42 && b[11]===0x50) return 'image/webp';
  if (b[4]===0x66 && b[5]===0x74 && b[6]===0x79 && b[7]===0x70) return 'image/heic';
  return '';
}
const GEMINI_OK = ['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf'];

let b64 = '', mime = '', ok = false, debug = '';
try {
  // Prefer GET /media/{id} (returns the raw file reliably); fall back to link.
  let url = j.mediaId ? ('https://gate.whapi.cloud/media/' + j.mediaId) : j.link;
  let resp = await this.helpers.httpRequest({
    method: 'GET', url, encoding: 'arraybuffer',
    headers: token ? { Authorization: 'Bearer ' + token } : {},
    returnFullResponse: true,
  });
  let buf = Buffer.isBuffer(resp.body) ? resp.body : Buffer.from(resp.body);

  // If the media-id route gave nothing useful, try the link.
  if ((!buf || buf.length < 100) && j.link) {
    resp = await this.helpers.httpRequest({
      method: 'GET', url: j.link, encoding: 'arraybuffer',
      headers: token ? { Authorization: 'Bearer ' + token } : {},
      returnFullResponse: true,
    });
    buf = Buffer.isBuffer(resp.body) ? resp.body : Buffer.from(resp.body);
  }

  const sniffed = sniffMime(buf);
  const head = buf.slice(0, 16).toString('utf8'); // for debugging non-images
  debug = 'len=' + (buf ? buf.length : 0) + ' sniff=' + (sniffed || 'none') + ' head=' + head.replace(/[^\x20-\x7e]/g,'.');

  if (sniffed && GEMINI_OK.includes(sniffed)) {
    mime = sniffed;
    b64 = buf.toString('base64').replace(/^data:[^;]+;base64,/, '');
    ok = b64.length > 0;
  } else {
    // Not a Gemini-supported file (maybe an HTML/JSON error page).
    ok = false;
    mime = sniffed || '';
  }
} catch (e) {
  debug = 'fetch_error=' + (e.message || e);
  ok = false;
}

// Prompt: classify, and for a receipt read the PAYER (customer), NOT the payee.
const promptText = 'אתה בודק תמונה או מסמך שלקוח שלח לעסק להדפסה על בגדים. קבע אם זו אסמכתא/הוכחת תשלום (העברה בנקאית, ביט, פייבוקס, צילום מסך של תשלום, קבלה) או גרפיקה/קובץ אמנות. אם זו אסמכתא תשלום - חלץ את שם המשלם (מי ששלח/העביר את הכסף), כלומר שם הלקוח. אל תיקח את שם המקבל של הכסף - המקבל הוא תמיד "טי סנטר" / "T center" / "לטי סנטר טקסטיל" / חשבון העסק, ואותו צריך להתעלם ולא להחזיר. אם רואים "מאת/שולח/From" קח את זה; אם רואים "אל/לכבוד/זוכה/To" - זה המקבל, התעלם. חלץ גם את סכום התשלום (מספר בלבד, בלי שקל). החזר אך ורק JSON תקין אחד, בלי טקסט נוסף ובלי markdown, בפורמט: {"kind":"receipt"|"graphic","full_name":"<שם המשלם/הלקוח או ריק>","amount":<מספר או 0>}. אם זו גרפיקה: {"kind":"graphic","full_name":"","amount":0}.';

const geminiBody = ok ? {
  contents: [ { role: 'user', parts: [
    { text: promptText },
    { inlineData: { mimeType: mime, data: b64 } }
  ] } ],
  generationConfig: { temperature: 0, maxOutputTokens: 512, responseMimeType: 'application/json' }
} : null;

return [{ json: {
  ...j,
  vision_b64: b64,
  vision_mime: mime || 'image/jpeg',
  vision_ok: ok,
  vision_debug: debug,
  geminiBody
} }];

// Works whether we came from Gemini (has candidates) or the skip branch (no image).
const f = $('Vision: Fetch & B64').item.json;
let kind = 'graphic', fullName = '', amount = 0, parseDebug = '';

if (f.vision_ok) {
  try {
    const cands = $json.candidates || [];
    let txt = (cands[0] && cands[0].content && cands[0].content.parts && cands[0].content.parts[0] && cands[0].content.parts[0].text || '').trim();
    txt = txt.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();
    const m = txt.match(/\{[\s\S]*\}/);
    if (m) {
      const o = JSON.parse(m[0]);
      if (o.kind === 'receipt') kind = 'receipt';
      fullName = (o.full_name || '').toString().trim();
      // amount may arrive as "100", "100.00", or with stray chars -> coerce hard.
      amount = Number(String(o.amount == null ? 0 : o.amount).replace(/[^0-9.]/g,'')) || 0;
    } else if (/receipt/i.test(txt)) {
      kind = 'receipt';
    }
    parseDebug = 'raw=' + txt.slice(0,180);
  } catch (e) { kind = 'graphic'; parseDebug = 'err=' + (e.message || e); }
} else {
  kind = 'graphic';
  parseDebug = 'vision_ok=false';
}

return [{ json: { ...f, kind, rcpt_name: fullName, rcpt_amount: amount, needsVision: false, vision_parse_debug: parseDebug } }];

// Receipt branch: reuse Vision's already-downloaded bytes, or fetch if absent.
const meta = $('IF Is Receipt?').item.json;
const token = 'FDPRDy6fE6JVVUQPphKgaKECwSw6MagO';

let b64  = meta.vision_b64 || '';
let mime = meta.vision_mime || meta.mime || 'image/jpeg';

// Keyword path (no Vision) -> download now via media/{id}, fallback to link.
if (!b64) {
  try {
    let url = meta.mediaId ? ('https://gate.whapi.cloud/media/' + meta.mediaId) : meta.link;
    let resp = await this.helpers.httpRequest({
      method: 'GET', url, encoding: 'arraybuffer',
      headers: token ? { Authorization: 'Bearer ' + token } : {},
      returnFullResponse: true,
    });
    let buf = Buffer.isBuffer(resp.body) ? resp.body : Buffer.from(resp.body);
    if ((!buf || buf.length < 100) && meta.link) {
      resp = await this.helpers.httpRequest({
        method: 'GET', url: meta.link, encoding: 'arraybuffer',
        headers: token ? { Authorization: 'Bearer ' + token } : {},
        returnFullResponse: true,
      });
      buf = Buffer.isBuffer(resp.body) ? resp.body : Buffer.from(resp.body);
    }
    b64 = buf.toString('base64').replace(/^data:[^;]+;base64,/, '');
  } catch (e) { b64 = ''; }
}

return [{ json: {
  chat_id: meta.chatId,
  phone: meta.phone,
  file_b64: b64,
  mime,
  filename: meta.filename || ('receipt_' + Date.now() + '.jpg'),
  caption: meta.caption || '',
  senderName: meta.senderName || '',
  rcpt_name: meta.rcpt_name || '',
  rcpt_amount: Number(meta.rcpt_amount) || 0
} }];

// Normalize Hebrew/Latin names for fuzzy compare (strip spaces, quotes, punctuation).
function norm(s){
  return (s||'').toString().toLowerCase()
    .replace(/[׳״'"`]/g,'')                 // hebrew geresh/gershayim + quotes
    .replace(/\b(בעמ|בע"מ|בעם|ltd|inc)\b/g,'')        // company suffixes
    .replace(/[^֐-׿a-z0-9]/g,'')             // keep only hebrew+latin+digits
    .trim();
}
const meta = $('Receipt: Download').item.json;
const rcptName = norm(meta.rcpt_name);
const rcptAmount = Number(meta.rcpt_amount) || 0;

const rows = items.map(i => i.json).filter(r => r && r.chat_id);
const open = rows.filter(r => r.status === 'open');
open.sort((a,b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

// amount tolerance: exact, or within 1 (rounding on the transfer)
const amtEq = (a,b) => Math.abs(Number(a||0) - Number(b||0)) <= 1;
const nameEq = (a) => {
  const o = norm(a);
  if (!rcptName || !o) return false;
  return o === rcptName || o.includes(rcptName) || rcptName.includes(o);
};

let target = null, matchType = 'none';
// 1) best: name AND amount -> safe to auto-pay
target = open.find(r => amtEq(r.total, rcptAmount) && nameEq(r.invoice_name));
if (target) matchType = 'name_amount';
// 2) amount matches but name doesn't -> human confirm
if (!target) {
  const byAmt = open.find(r => amtEq(r.total, rcptAmount));
  if (byAmt) { target = byAmt; matchType = 'amount_only'; }
}
// 3) name matches but amount missing/zero (Vision couldn't read amount) -> human confirm
if (!target && rcptAmount === 0) {
  const byName = open.find(r => nameEq(r.invoice_name));
  if (byName) { target = byName; matchType = 'name_only'; }
}
// 4) nothing matched but the customer has exactly ONE open order -> human confirm
if (!target && open.length === 1) {
  target = open[0]; matchType = 'single_open';
}

// autoPaid ONLY on a full name+amount match. Everything else with an order -> needsConfirm.
const autoPaid    = (matchType === 'name_amount');
const needsConfirm = (!!target && !autoPaid);   // order exists but not certain
const hasOpenOrder = !!target;

return [{ json: {
  chat_id: meta.chat_id,
  phone: meta.phone,
  senderName: meta.senderName || meta.rcpt_name || '',
  rcpt_name: meta.rcpt_name || '',
  rcpt_amount: rcptAmount,
  hasOpenOrder,
  autoPaid,
  needsConfirm,
  matchType,
  orderId: target ? target.id : null,
  total: target ? (target.total || '') : '',
  invoice_name: target ? (target.invoice_name || '') : '',
  payment_link: target ? (target.payment_link || '') : ''
} }];

