const msgs = ($json.body && $json.body.messages) || [];
const m = msgs[0] || {};
if (m.from_me === true) return [];
if (m.type !== 'text') return [];
const txt = (m.text && m.text.body ? m.text.body : '').toString().trim();
if (!txt) return [];

const chatId = m.chat_id;
const urls = txt.match(/https?:\/\/\S+/gi) || [];
// "link-only" = contains a URL and very little else (<= 8 non-url words)
const stripped = txt.replace(/https?:\/\/\S+/gi, '').trim();
const wordCount = stripped ? stripped.split(/\s+/).length : 0;
const isLinkOnly = urls.length > 0 && wordCount <= 8;

// Payment-context words make it a payment link even with more text.
const PAYWORD = /(תשלום|העברה|שילמתי|שולם|ביט|bit|paybox|פייבוקס|אסמכת|קבלה|חשבונית|paid|payment|transfer)/i;
const looksPayment = urls.length > 0 && (isLinkOnly || PAYWORD.test(stripped));

if (!looksPayment) return [];
return [{ json: { chatId, isLink: true } }];

// === Approval gate: release the payment link ONLY on a real confirmation ===
// Two ways to confirm:
//   (1) the customer's message is essentially a standalone yes (short, or the
//       approval word IS the message) — not a "כן" buried in an answer about
//       delivery/size/color;
//   (2) the customer REPLIED (quoted) the bot's summary message with a yes.
const src = $('Parse Order').first().json;
const incoming = ($('Bot Allowed?').item.json.mergedText || '').toString().replace(/\[המערכת:[^\]]*\]/g, '').trim();

// quoted content of a WhatsApp reply, if any (threaded from the webhook)
let quoted = '';
try {
  const m = $('Webhook (WHAPI In)').item.json.body.messages[0];
  quoted = (m && m.context && (m.context.quoted_content || m.context.quoted_id)) ? String(m.context.quoted_content || '') : '';
} catch (e) { quoted = ''; }

const norm = (s) => s.toLowerCase()
  .replace(/[\u0591-\u05c7]/g, '')       // strip nikud
  .replace(/[!?.,\u05f3\u05f4"'`\-]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const t = norm(incoming);
const words = t ? t.split(' ') : [];

const APPROVE = /(^|\s)(כן|מאשר|מאשרת|אשר|אישרתי|לאשר|סגור|סוגרים|נסגור|סבבה|מעולה סגרנו|יאללה סגור|אפשר לשלם|שלח לי לינק|שלח לינק|תשלח לינק|תשלח את הלינק)(\s|$)/;
const REFUSE  = /(^|\s)(לא|רגע|חכה|תקן|שנה|בהמשך|אולי|עדיין|לא בטוח)(\s|$)/;

const hasApprove = APPROVE.test(t);
const hasRefuse  = REFUSE.test(t);

// (1) standalone-ish: <= 4 words total, or the only "real" word is the yes.
// answering a sub-question (delivery/pickup/size/color/address) is NOT an order confirm
const SUBQ = /(משלוח|איסוף|מידה|מידות|צבע|כתובת|קדמי|אחורי|גדול|קטן|רחוב|עיר|דחוף|מתי|כמה)/;
const standalone = hasApprove && words.length <= 4 && !SUBQ.test(t);

// (2) reply that quotes our summary text (we put a price/סיכום in it).
const repliedToSummary = !!quoted && /(סיכום|לאשר|סה"?כ|מחיר|לתשלום|הזמנה)/.test(norm(quoted)) && hasApprove;

const isApproval = (standalone || repliedToSummary) && !hasRefuse;
const allowLink = src.isOrder === true ? isApproval : false;

return [{ json: { ...src, isOrder: allowLink,
  gate_debug: { hasApprove, hasRefuse, words: words.length, standalone, repliedToSummary, quoted: quoted.slice(0,60) } } }];

const b = $json.body || {};
const m = (b.messages && b.messages[0]) || {};
return [{ json: {
  chat_id: m.chat_id || '',
  from_me: m.from_me === true,
  msg_type: m.type || '',
  source: m.source || '',
  from_name: m.from_name || '',
  msg_count: (b.messages || []).length,
  payload: b              // OBJECT -> stored as real jsonb
} }];

// Quick-link: owner types "שלח לינק <סכום>" in the orders group. Mints a GENERIC
// unassigned payment link on T-CENTER's own name and posts it back to the group.
const msg = $json.body.messages[0];
const body = String(msg.text && msg.text.body || '');
// amount = first number anywhere after the word 'לינק' (handles 'ל500', '500 שקל', '5000ש', 'ל-500', '1,200')
const parts = body.split('לינק');
const after = parts.length > 1 ? parts.slice(1).join('לינק') : body;
const numMatch = after.match(/(\d[\d.,]*)/);
if (!numMatch) { return [{ json: { __qlFail: true, reason: 'לא צוין סכום' } }]; }
const amount = Number(String(numMatch[1]).replace(/,/g,''));
if (!amount || amount <= 0 || amount > 1000000) { return [{ json: { __qlFail: true, reason: 'סכום לא תקין: ' + numMatch[1] } }]; }
// Israel local time for the description (DST-safe)
const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', hour12: false }).formatToParts(new Date()).map(x => [x.type, x.value]));
const hh = p.hour === '24' ? '00' : p.hour;
const desc = 'הוצאת לינק ידני בשעה ' + hh + ':' + p.minute + ' (' + p.day + '/' + p.month + ') — לינק גנרי ללא שיוך';
return [{ json: {
  __ql: true,
  total: amount,
  desc: desc,
  o_invoice_name: 'טי סנטר',
  businessPhone: '0507506702',
  groupChatId: '120{{TPL:NOTIFY_GROUP_ID}}'
} }];

